241	    // §2.17 internal SECDED codec — a SIMPLIFIED 8-bit syndrome proxy over an
242	    // 8-byte data word (NOT a full Hamming(72,64) matrix). honest E3: this
243	    // models the SECDED *check/correct logic* being faulty, not cycle-exact
244	    // DRAM ECC. syndrome = XOR of all data bytes (1-byte parity-like check).
245	    uint8_t
246	    CHAOSMem::secdedSyndrome(const uint8_t *data8)
247	    {
248	        uint8_t s = 0;
249	        for (int i = 0; i < 8; i++) s ^= data8[i];
250	        return s;
251	    }
252	
253	    // §2.17 ecc_logic_fault: corrupt the syndrome bit (not the data), then run
254	    // decode (recompute syndrome vs the stored — but here we model the FAULTY
255	    // logic by XOR-ing the recomputed syndrome with xor_mask, simulating a
256	    // miscorrection: the 'corrected' value flips the wrong bit -> a 1-bit data
257	    // error becomes a 2-bit error after the faulty 'correction'). Returns true.
258	    bool
259	    CHAOSMem::applyEccLogicFault(uint8_t *data8, uint8_t xor_mask)
260	    {
261	        if (!data8) return false;
262	        // Faulty SECDED: the syndrome (ECC logic) bit is flipped. A 1-bit data
263	        // error would be 'corrected' using the WRONG syndrome -> flips a
264	        // DIFFERENT bit (mis-correction: 1-bit -> 2-bit, undetectable as 2-bit
265	        // if the faulty syndrome happens to also be valid for a 2-bit pattern).
266	        // Model: flip a data bit guided by the faulty syndrome (xor_mask picks
267	        // which data bit the faulty logic 'thinks' is wrong).
268	        if (xor_mask == 0) return false;
269	        // pick the lowest set bit of xor_mask as the mis-corrected position
270	        int pos = __builtin_ctz(xor_mask) % 64;
271	        data8[pos / 8] ^= (1 << (pos % 8));  // mis-correct: flip a data bit
272	        if (write_log) {
273	            *(log_stream->stream()) << "    protection: §2.17 ecc_logic_fault "
274	                << "mis-corrected data bit " << pos
275	                << " (syndrome logic faulty -> 1-bit err -> wrong-bit fix)\n";
276	        }
277	        return true;
278	    }
