280	    unsigned char 
281	    CHAOSMem::generateRandomMask(std::mt19937 &rng, int bits_to_change, int len)
282	    {
283	        unsigned char mask = 0;
284	        std::uniform_int_distribution<int> bitDist(0, len-1);
285	
286	        for (int i = 0; i < bits_to_change; i++) {
287	            // G1/G4: unsigned shift (1U <<), no signed-shift UB for bit>=31.
288	            mask |= (1U << bitDist(rng));
289	        }
290	        return mask;
291	    }
