32	    CHAOSL1DForward::inWindow() {
33	        // Frequency-correct: use the CPU's actual clock period for the
34	        // cycles->ticks conversion (C0 2GHz=500t/cyc, C2-KP 2.6GHz~385t/cyc).
35	        // The old *1000 assumed 1GHz and never opened the window on C2.
36	        if (!cpu) return false;
37	        auto *o3cpu = dynamic_cast<o3::CPU *>(cpu);
38	        if (!o3cpu) return false;
39	        Tick now = curTick();
40	        Tick period = o3cpu->clockPeriod();
41	        Tick f = first_clock * period;
42	        if (now < f) return false;
43	        if (last_clock != 0 && now > last_clock * period) return false;
44	        return true;
45	    }
